use std::collections::HashSet;

/// Returns true iff `val` occurs at some in-bounds index of `s`.
pub fn slice_contains(s: &[i32], val: i32) -> bool {
    s.iter().any(|&x| x == val)
}

/// Returns true iff there exist in-bounds indices i, j such that `a[i] == b[j]`.
pub fn has_common_element(a: &[i32], b: &[i32]) -> bool {
    if a.is_empty() || b.is_empty() {
        return false;
    }

    // Build a set from the smaller slice to minimize memory usage.
    let (small, large) = if a.len() <= b.len() { (a, b) } else { (b, a) };

    let set: HashSet<i32> = small.iter().copied().collect();
    large.iter().any(|&x| set.contains(&x))
}

